window.CSP_hydrate = function (key, seeds) {
  var flag = key + '_seeded_v1';
  try {
    if (!localStorage.getItem(flag)) {
      var cur = [];
      try { cur = JSON.parse(localStorage.getItem(key) || '[]'); } catch (e) { cur = []; }
      if (!Array.isArray(cur)) cur = [];
      var have = {};
      cur.forEach(function (i) { if (i && i.id != null) have[i.id] = true; });
      var merged = seeds.filter(function (s) { return !have[s.id]; }).concat(cur);
      localStorage.setItem(key, JSON.stringify(merged));
      localStorage.setItem(flag, '1');
    }
  } catch (e) {}
  try { return JSON.parse(localStorage.getItem(key) || '[]'); }
  catch (e) { return seeds.slice(); }
};
